import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Animated, Easing, Image, Linking, SafeAreaView, ScrollView, StyleSheet, Text, TextInput, TouchableOpacity, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';

const C={ink:'#18201D',muted:'#66706B',green:'#315F4A',dark:'#244838',soft:'#E7EFEA',bg:'#F4F5F2',white:'#FFF',line:'#DDE2DE',amber:'#9A6A25',amberSoft:'#F7EEDF',red:'#A74642'};
const DAYS=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
const MEALS={
  'Chicken burritos':{time:30,ingredients:[['Chicken breast',1,'pack','2026-09-09',true],['Wraps',1,'pack',null,false],['Rice',1,'pouch',null,false],['Cheddar',1,'pack','2026-09-18',true],['Tomatoes',2,'items','2026-09-12',true]]},
  'Mexican rice pan':{time:25,ingredients:[['Beef mince',1,'pack','2026-09-10',true],['Mexican rice',1,'pouch',null,false],['Peppers',2,'items','2026-09-13',true],['Chorizo',1,'pack','2026-09-20',true]]},
  'Pizza night':{time:20,ingredients:[['Frozen pizza',2,'items',null,false],['Garlic bread',1,'pack',null,false]]},
  'Sausage pasta bake':{time:40,ingredients:[['Sausages',1,'pack','2026-09-11',true],['Pasta',1,'pack',null,false],['Pasta sauce',1,'jar',null,false],['Mozzarella',1,'pack','2026-09-15',true]]},
  'Chilli con carne':{time:35,ingredients:[['Beef mince',1,'pack','2026-09-10',true],['Kidney beans',1,'tin',null,false],['Chopped tomatoes',1,'tin',null,false],['Rice',1,'pack',null,false]]},
  'Chicken burgers':{time:25,ingredients:[['Chicken burgers',2,'items','2026-09-10',true],['Burger buns',1,'pack','2026-09-12',true],['Oven chips',1,'bag',null,false]]},
  'Jacket potatoes':{time:60,ingredients:[['Baking potatoes',2,'items','2026-09-16',true],['Tuna',1,'tin',null,false],['Cheddar',1,'pack','2026-09-18',true]]},
};
const initialCurrent={'Monday':'Chicken burritos','Tuesday':'Mexican rice pan','Wednesday':'Pizza night','Thursday':'Sausage pasta bake','Friday':'Chilli con carne','Saturday':'Chicken burgers','Sunday':'Jacket potatoes'};
const initialNext={'Monday':'Sausage pasta bake','Tuesday':'Chicken burritos','Wednesday':'Pizza night','Thursday':'Mexican rice pan','Friday':'Chilli con carne','Saturday':'Chicken burgers','Sunday':'Jacket potatoes'};
const money=n=>`£${(n/100).toFixed(2)}`;
const shops=[['Tesco',5148],['Morrisons',5295],["Sainsbury's",5372]];
const VAN_IMAGE='data:image/jpeg;base64,';
const LOGO_IMAGE='data:image/jpeg;base64,';

const OPEN_VAN_IMAGE='data:image/jpeg;base64,';

const MATCHED_CLOSED_VAN_IMAGE='data:image/jpeg;base64,';
const MATCHED_OPEN_VAN_IMAGE='data:image/jpeg;base64,';

export default function App(){
 const[splashDone,setSplashDone]=useState(false),[started,setStarted]=useState(false),[tab,setTab]=useState('This Week'),[page,setPage]=useState('');
 const[shopDay,setShopDay]=useState('Friday'),[current,setCurrent]=useState(initialCurrent),[planWeek,setPlanWeek]=useState(1);
 const[futurePlans,setFuturePlans]=useState(()=>Object.fromEntries(Array.from({length:8},(_,i)=>[i+1,{...initialNext}])));
 const[outcomes,setOutcomes]=useState({}),[extrasByWeek,setExtrasByWeek]=useState({1:['Toilet roll','Toothpaste']}),[extra,setExtra]=useState('');
 const[itemHistory,setItemHistory]=useState({'Toilet roll':{orders:3,every:3},'Toothpaste':{orders:2,every:5},'Kitchen roll':{orders:4,every:2}}),[showLow,setShowLow]=useState(true);
 const[checkoutShop,setCheckoutShop]=useState(''),[delivery,setDelivery]=useState(''),[arrivalLogged,setArrivalLogged]=useState(false);
 const[dates,setDates]=useState({'Chicken breast':'2026-09-09','Beef mince':'2026-09-10','Sausages':'2026-09-11'}),[pantry,setPantry]=useState({'Chicken breast':1,'Wraps':1,'Rice':2,'Cheddar':1,'Tomatoes':4,'Milk':1});
 const next=futurePlans[planWeek],basketExtras=extrasByWeek[planWeek]||[];
 const basket=useMemo(()=>buildBasket(next,basketExtras),[next,basketExtras]);
 const suggestion=useMemo(()=>findExpirySuggestion(current,dates),[current,dates]);
 const chooseMeal=(day,meal)=>{setFuturePlans(p=>({...p,[planWeek]:{...p[planWeek],[day]:meal}}));setPage('');setTab('Plan Shop')};
 const addNonFood=name=>{if(!name)return;setExtrasByWeek(p=>({...p,[planWeek]:[...new Set([...(p[planWeek]||[]),name])]}));setItemHistory(p=>({...p,[name]:{orders:(p[name]?.orders||0)+1,every:p[name]?.every||3}}))};
 const finishDay=(day,type)=>{setOutcomes(p=>({...p,[day]:type}));if(type==='Cooked'){const meal=MEALS[current[day]];setPantry(p=>{let n={...p};meal.ingredients.forEach(([name,qty])=>n[name]=Math.max(0,(n[name]||0)-qty));return n})}};
 if(!splashDone)return <DeliverySplash onFinish={()=>setSplashDone(true)}/>;
 if(!started)return <SafeAreaView style={s.welcome}><Image source={{uri:LOGO_IMAGE}} style={s.logoImage}/><Text style={s.welcomeTitle}>Our Weekly Shop</Text><Text style={s.welcomeSub}>Plan once. Stay organised all week.</Text><Text style={s.copy}>Choose when you normally shop. We will keep this week’s meals separate from the shop you are planning for next week.</Text><Text style={s.label}>MY WEEKLY SHOP DAY</Text><View style={s.dayPicker}>{['Thursday','Friday','Saturday','Sunday'].map(d=><TouchableOpacity key={d} style={[s.dayPill,shopDay===d&&s.dayPillOn]} onPress={()=>setShopDay(d)}><Text style={[s.dayPillText,shopDay===d&&s.dayPillTextOn]}>{d.slice(0,3)}</Text></TouchableOpacity>)}</View><TouchableOpacity style={s.button} onPress={()=>setStarted(true)}><Text style={s.buttonText}>Continue to my week</Text></TouchableOpacity><Text style={s.demo}>INTERACTIVE WORKFLOW PREVIEW</Text></SafeAreaView>;
 return <SafeAreaView style={s.safe}><ScrollView contentContainerStyle={s.content} showsVerticalScrollIndicator={false}>
  {page?<Sub page={page} back={()=>setPage('')} next={next} chooseMeal={chooseMeal} shopDay={shopDay} setShopDay={setShopDay} basket={basket} checkoutShop={checkoutShop} setCheckoutShop={setCheckoutShop} delivery={delivery} setDelivery={setDelivery} setArrivalLogged={setArrivalLogged} dates={dates} setDates={setDates} addNonFood={addNonFood} itemHistory={itemHistory}/>:<>
   {tab==='This Week'&&<ThisWeek plan={current} outcomes={outcomes} finishDay={finishDay} suggestion={suggestion} setCurrent={setCurrent}/>} 
   {tab==='Plan Shop'&&<PlanShop plan={next} shopDay={shopDay} open={setPage} basket={basket} planWeek={planWeek} setPlanWeek={setPlanWeek} showLow={showLow} setShowLow={setShowLow} addNonFood={addNonFood}/>} 
   {tab==='Basket'&&<Basket basket={basket} extras={basketExtras} setExtras={items=>setExtrasByWeek(p=>({...p,[planWeek]:items}))} extra={extra} setExtra={setExtra} open={setPage} checkoutShop={checkoutShop} delivery={delivery} addNonFood={addNonFood}/>} 
   {tab==='At Home'&&<AtHome pantry={pantry} arrivalLogged={arrivalLogged} delivery={delivery} dates={dates} open={setPage}/>} 
   {tab==='Account'&&<Account shopDay={shopDay} open={setPage} reset={()=>setStarted(false)}/>} 
  </>}
 </ScrollView>{!page&&<Nav tab={tab} setTab={setTab}/>}</SafeAreaView>
}

function DeliverySplash({onFinish}){
 const vanX=useRef(new Animated.Value(-520)).current,openOpacity=useRef(new Animated.Value(0)).current,logoY=useRef(new Animated.Value(16)).current,logoScale=useRef(new Animated.Value(.16)).current,logoOpacity=useRef(new Animated.Value(0)).current,tagOpacity=useRef(new Animated.Value(0)).current,screenOpacity=useRef(new Animated.Value(1)).current;
 const closedOpacity=openOpacity.interpolate({inputRange:[0,.72,1],outputRange:[1,1,0]});
 useEffect(()=>{Animated.sequence([
  Animated.timing(vanX,{toValue:130,duration:1250,easing:Easing.out(Easing.cubic),useNativeDriver:true}),
  Animated.delay(260),
  Animated.timing(openOpacity,{toValue:1,duration:520,easing:Easing.inOut(Easing.cubic),useNativeDriver:true}),
  Animated.timing(logoOpacity,{toValue:1,duration:90,useNativeDriver:true}),
  Animated.parallel([Animated.timing(logoY,{toValue:0,duration:850,easing:Easing.out(Easing.cubic),useNativeDriver:true}),Animated.timing(logoScale,{toValue:1,duration:850,easing:Easing.out(Easing.back(1.08)),useNativeDriver:true})]),
  Animated.delay(260),
  Animated.timing(vanX,{toValue:590,duration:900,easing:Easing.in(Easing.cubic),useNativeDriver:true}),
  Animated.timing(tagOpacity,{toValue:1,duration:380,useNativeDriver:true}),
  Animated.delay(650),Animated.timing(screenOpacity,{toValue:0,duration:350,useNativeDriver:true})
 ]).start(({finished})=>{if(finished)onFinish()})},[]);
 return <Animated.View style={[s.splash,{opacity:screenOpacity}]}><View style={s.splashStage}><Animated.View style={[s.vanImageWrap,{opacity:closedOpacity,transform:[{translateX:vanX}]}]}><Image source={{uri:MATCHED_CLOSED_VAN_IMAGE}} style={s.vanImage}/></Animated.View><Animated.View style={[s.vanImageWrap,{opacity:openOpacity,transform:[{translateX:vanX}]}]}><Image source={{uri:MATCHED_OPEN_VAN_IMAGE}} style={s.vanImage}/></Animated.View><Animated.View style={[s.splashLogo,{opacity:logoOpacity,transform:[{translateY:logoY},{scale:logoScale}]}]}><Image source={{uri:LOGO_IMAGE}} style={s.splashLogoImage}/></Animated.View></View><Animated.View style={{opacity:tagOpacity,alignItems:'center'}}><Text style={s.splashTitle}>Our Weekly Shop</Text><Text style={s.splashTag}>Your weekly shop, at the best price.</Text></Animated.View></Animated.View>;
}

function buildBasket(plan,extras){const map={};Object.values(plan).forEach(mealName=>{const meal=MEALS[mealName];if(meal)meal.ingredients.forEach(([name,qty,unit,,dated])=>{if(!map[name])map[name]={name,qty:0,unit,dated,meals:[]};map[name].qty+=qty;if(!map[name].meals.includes(mealName))map[name].meals.push(mealName)})});extras.forEach(name=>map[name]={name,qty:1,unit:'item',dated:false,meals:['Household']});return Object.values(map)}
function findExpirySuggestion(plan,dates){
 for(const day of DAYS){
  const meal=MEALS[plan[day]];
  if(!meal)continue;
  for(const [name] of meal.ingredients){
   const plannedDate=new Date(`2026-09-${8+DAYS.indexOf(day)}T12:00:00`);
   const useBy=dates[name]?new Date(`${dates[name]}T12:00:00`):null;
   if(useBy&&useBy<plannedDate){
    return {name,meal:plan[day],from:day,to:DAYS[Math.max(0,useBy.getDate()-8)]||'Monday',date:dates[name]};
   }
  }
 }
 return null;
}

function ThisWeek({plan,outcomes,finishDay,suggestion,setCurrent}){const[today]=useState('Monday');return <><Header overline="MEAL PLAN · THIS WEEK" title="Your week" sub="Everything already planned for the next seven days."/>{suggestion&&<View style={s.alert}><View style={s.alertIcon}><Ionicons name="time-outline" size={20} color={C.amber}/></View><View style={{flex:1}}><Text style={s.alertTitle}>Use-by date suggestion</Text><Text style={s.alertText}>{suggestion.name} is dated {niceDate(suggestion.date)}. Move {suggestion.meal} from {suggestion.from} to {suggestion.to}?</Text><TouchableOpacity onPress={()=>{const a=plan[suggestion.from],b=plan[suggestion.to];setCurrent(p=>({...p,[suggestion.from]:b,[suggestion.to]:a}))}}><Text style={s.link}>Move meal automatically</Text></TouchableOpacity></View></View>}
 <View style={s.weekCard}>{DAYS.map((day,i)=>{const status=outcomes[day];return <View key={day} style={[s.calendarRow,day===today&&s.todayRow]}><View style={s.date}><Text style={[s.dayShort,day===today&&{color:C.green}]}>SEP</Text><Text style={s.dateNo}>{8+i}</Text></View><View style={{flex:1}}><View style={s.dayHeading}><Text style={s.dayName}>{day}</Text>{day===today&&<Text style={s.today}>TODAY</Text>}</View><Text style={[s.mealName,status&&s.crossed]}>{plan[day]}</Text><Text style={s.mealMeta}>{MEALS[plan[day]].time} minutes · Dinner</Text>{day===today&&!status&&<View style={s.outcomeRow}><SmallButton icon="checkmark" text="Cooked" onPress={()=>finishDay(day,'Cooked')}/><SmallButton icon="restaurant-outline" text="Ate out" onPress={()=>finishDay(day,'Ate out')} pale/><SmallButton icon="bag-handle-outline" text="Takeaway" onPress={()=>finishDay(day,'Takeaway')} pale/></View>}{status&&<View style={s.status}><Ionicons name={status==='Cooked'?'checkmark-circle':'information-circle'} size={15} color={C.green}/><Text style={s.statusText}>{status}{status==='Cooked'?' · ingredients removed from home stock':' · no ingredients used'}</Text></View>}</View></View>})}</View>
 <View style={s.info}><Ionicons name="notifications-outline" size={19} color={C.green}/><Text style={s.infoText}>Each evening, the app will remind you to confirm whether the planned meal was cooked, skipped or replaced.</Text></View></>}

function PlanShop({plan,shopDay,open,basket,planWeek,setPlanWeek,showLow,setShowLow,addNonFood}){const start=15+(planWeek-1)*7;return <><Header overline="FUTURE MEAL PLANS" title="Plan your shop" sub={`Your shop day is ${shopDay}. Plan up to eight weeks ahead.`}/><View style={s.weekNavigator}><TouchableOpacity disabled={planWeek===1} onPress={()=>setPlanWeek(w=>w-1)}><Ionicons name="chevron-back" size={20} color={planWeek===1?C.line:C.green}/></TouchableOpacity><View style={{alignItems:'center'}}><Text style={s.weekNavTitle}>{planWeek===1?'Next week':`Week ${planWeek}`}</Text><Text style={s.weekNavDate}>{start}–{start+6} September</Text></View><TouchableOpacity disabled={planWeek===8} onPress={()=>setPlanWeek(w=>w+1)}><Ionicons name="chevron-forward" size={20} color={planWeek===8?C.line:C.green}/></TouchableOpacity></View><Button text="Add non-food items" icon="add" pale onPress={()=>open('NonFood')}/>{showLow&&<View style={s.lowPrompt}><View style={s.alertIcon}><Ionicons name="repeat-outline" size={20} color={C.amber}/></View><View style={{flex:1}}><Text style={s.alertTitle}>Running low on toilet roll?</Text><Text style={s.alertText}>You normally reorder this around every 3 weeks.</Text><View style={s.promptActions}><TouchableOpacity onPress={()=>{addNonFood('Toilet roll');setShowLow(false)}}><Text style={s.link}>Add to this shop</Text></TouchableOpacity><TouchableOpacity onPress={()=>setShowLow(false)}><Text style={s.notNow}>Not now</Text></TouchableOpacity></View></View></View>}<View style={s.progress}><View style={s.progressTop}><Text style={s.progressTitle}>Meal plan</Text><Text style={s.progressCount}>7 of 7 dinners planned</Text></View><View style={s.track}><View style={[s.trackFill,{width:'100%'}]}/></View></View><View style={s.weekCard}>{DAYS.map((day,i)=><TouchableOpacity key={day} style={s.planRow} onPress={()=>open(`Choose:${day}`)}><View style={s.date}><Text style={s.dayShort}>SEP</Text><Text style={s.dateNo}>{start+i}</Text></View><View style={{flex:1}}><Text style={s.dayName}>{day}</Text><Text style={s.mealName}>{plan[day]}</Text><Text style={s.mealMeta}>{MEALS[plan[day]].time} minutes · ingredients added</Text></View><Ionicons name="chevron-forward" size={18} color={C.muted}/></TouchableOpacity>)}</View><View style={s.basketCallout}><View style={s.iconBox}><Ionicons name="basket-outline" size={21} color={C.green}/></View><View style={{flex:1}}><Text style={s.rowTitle}>Shopping list created</Text><Text style={s.rowDetail}>{basket.length} products calculated for this week</Text></View></View></>}

function Basket({basket,extras,setExtras,extra,setExtra,open,checkoutShop,delivery,addNonFood}){const add=()=>{if(extra.trim()){addNonFood(extra.trim());setExtra('')}};return <><Header overline="SELECTED WEEK" title="Your basket" sub="Meal ingredients and anything else your household needs."/><View style={s.addBar}><Ionicons name="add" size={20} color={C.green}/><TextInput value={extra} onChangeText={setExtra} onSubmitEditing={add} placeholder="Add toilet roll, toothpaste, batteries…" placeholderTextColor={C.muted} style={s.input}/><TouchableOpacity onPress={add}><Text style={s.link}>Add</Text></TouchableOpacity></View><Text style={s.sectionLabel}>MEAL INGREDIENTS</Text><View style={s.card}>{basket.filter(x=>x.meals[0]!=='Household').map(item=><Item key={item.name} item={item}/>)}</View><Text style={s.sectionLabel}>OTHER ITEMS</Text><View style={s.card}>{basket.filter(x=>x.meals[0]==='Household').map(item=><View key={item.name} style={s.itemRow}><View style={s.tick}><Ionicons name="checkmark" size={14} color={C.green}/></View><View style={{flex:1}}><Text style={s.rowTitle}>{item.name}</Text><Text style={s.rowDetail}>Added manually · reorder timing remembered</Text></View><TouchableOpacity onPress={()=>setExtras(extras.filter(x=>x!==item.name))}><Ionicons name="trash-outline" size={18} color={C.muted}/></TouchableOpacity></View>)}</View>{checkoutShop?<View style={s.confirm}><Ionicons name="checkmark-circle" size={22} color={C.green}/><View style={{flex:1}}><Text style={s.confirmTitle}>Basket sent to {checkoutShop}</Text><Text style={s.rowDetail}>{delivery?`Expected ${delivery}`:'Add the delivery or collection time when checkout is complete.'}</Text></View></View>:null}<Button text={checkoutShop?'Update delivery details':'Compare and choose supermarket'} icon="stats-chart-outline" onPress={()=>open('Compare')}/></>}
function Item({item}){return <View style={s.itemRow}><View style={s.tick}><Ionicons name="checkmark" size={14} color={C.green}/></View><View style={{flex:1}}><Text style={s.rowTitle}>{item.name}</Text><Text style={s.rowDetail}>{item.qty} {item.unit}{item.qty>1?'s':''} · {item.meals.slice(0,2).join(', ')}</Text></View>{item.dated&&<Text style={s.fresh}>FRESH</Text>}</View>}

function AtHome({pantry,arrivalLogged,delivery,dates,open}){return <><Header overline="HOUSEHOLD STOCK" title="What’s at home" sub="Updated automatically as shopping arrives and meals are completed."/>{delivery&&!arrivalLogged&&<View style={s.arrival}><Ionicons name="cube-outline" size={22} color={C.green}/><View style={{flex:1}}><Text style={s.rowTitle}>Your shop is due {delivery}</Text><Text style={s.rowDetail}>When it arrives, log the dates on short-life products.</Text></View><TouchableOpacity onPress={()=>open('Dates')}><Text style={s.link}>Log dates</Text></TouchableOpacity></View>}<Text style={s.sectionLabel}>SHORT-LIFE PRODUCTS</Text><View style={s.card}>{Object.entries(dates).map(([name,date])=><View key={name} style={s.itemRow}><View style={s.iconBox}><Ionicons name="calendar-outline" size={18} color={C.green}/></View><View style={{flex:1}}><Text style={s.rowTitle}>{name}</Text><Text style={s.rowDetail}>Use by {niceDate(date)}</Text></View></View>)}</View><Text style={s.sectionLabel}>CUPBOARD AND FRIDGE</Text><View style={s.card}>{Object.entries(pantry).filter(([,q])=>q>0).map(([name,q])=><View key={name} style={s.itemRow}><View style={s.iconBox}><Ionicons name="cube-outline" size={18} color={C.green}/></View><View style={{flex:1}}><Text style={s.rowTitle}>{name}</Text><Text style={s.rowDetail}>{q} remaining</Text></View></View>)}</View></>}

function Account({shopDay,open,reset}){return <><Header overline="ACCOUNT" title="Your household" sub="Preferences that power your weekly routine."/><View style={s.card}><Setting icon="people-outline" name="Household members" detail="Jack and Gemma"/><Setting icon="calendar-outline" name="Weekly shop day" detail={shopDay} onPress={()=>open('ShopDay')}/><Setting icon="storefront-outline" name="Supermarket accounts" detail="Connect when partners approve access"/><Setting icon="notifications-outline" name="Reminders" detail="Meal and delivery prompts enabled"/><Setting icon="shield-checkmark-outline" name="Privacy and permissions" detail="You control every connection"/></View><Button text="Preview setup again" pale onPress={reset}/></>}
function Setting({icon,name,detail,onPress}){return <TouchableOpacity disabled={!onPress} onPress={onPress} style={s.itemRow}><View style={s.iconBox}><Ionicons name={icon} size={19} color={C.green}/></View><View style={{flex:1}}><Text style={s.rowTitle}>{name}</Text><Text style={s.rowDetail}>{detail}</Text></View>{onPress&&<Ionicons name="chevron-forward" size={18} color={C.muted}/>}</TouchableOpacity>}

function Sub({page,back,next,chooseMeal,shopDay,setShopDay,basket,checkoutShop,setCheckoutShop,delivery,setDelivery,setArrivalLogged,dates,setDates,addNonFood,itemHistory}){
 if(page.startsWith('Choose:')){
  const day=page.split(':')[1];
  return <><Back onPress={back}/><Header overline="CHOOSE DINNER" title={day} sub="Selecting a meal updates your shopping list immediately."/><View style={s.card}>{Object.entries(MEALS).map(([name,meal])=><TouchableOpacity key={name} style={[s.mealChoice,next[day]===name&&s.mealChoiceOn]} onPress={()=>chooseMeal(day,name)}><View style={s.iconBox}><Ionicons name="restaurant-outline" size={19} color={C.green}/></View><View style={{flex:1}}><Text style={s.rowTitle}>{name}</Text><Text style={s.rowDetail}>{meal.time} minutes · {meal.ingredients.length} ingredients</Text></View>{next[day]===name&&<Ionicons name="checkmark-circle" size={21} color={C.green}/>}</TouchableOpacity>)}</View></>;
 }
 if(page==='Compare')return <Compare back={back} basket={basket} checkoutShop={checkoutShop} setCheckoutShop={setCheckoutShop} delivery={delivery} setDelivery={setDelivery}/>;
 if(page==='Dates')return <Dates back={back} dates={dates} setDates={setDates} done={()=>{setArrivalLogged(true);back()}}/>;
 if(page==='NonFood')return <NonFood back={back} addNonFood={addNonFood} itemHistory={itemHistory}/>;
 if(page==='ShopDay')return <><Back onPress={back}/><Header overline="SHOP ROUTINE" title="Weekly shop day" sub="We will prompt you to plan the upcoming week before this day."/><View style={s.card}>{DAYS.map(day=><TouchableOpacity key={day} style={s.itemRow} onPress={()=>{setShopDay(day);back()}}><Text style={[s.rowTitle,{flex:1}]}>{day}</Text>{shopDay===day&&<Ionicons name="checkmark-circle" size={21} color={C.green}/>}</TouchableOpacity>)}</View></>;
 return null;
}

function NonFood({back,addNonFood,itemHistory}){const[query,setQuery]=useState('');const options=['Toilet roll','Toothpaste','Kitchen roll','Bin bags','AA batteries','Candles','Shampoo','Hand soap','Laundry detergent','Dishwasher tablets','Cleaning spray','Kitchen foil','Pet food'].filter(x=>x.toLowerCase().includes(query.toLowerCase()));return <><Back onPress={back}/><Header overline="NON-FOOD ITEMS" title="Add household essentials" sub="Search for anything you need. Reorder patterns are learned privately for future reminders."/><View style={s.addBar}><Ionicons name="search" size={19} color={C.muted}/><TextInput autoFocus value={query} onChangeText={setQuery} placeholder="Search household items" placeholderTextColor={C.muted} style={s.input}/></View><View style={s.card}>{options.map(name=><View key={name} style={s.itemRow}><View style={s.iconBox}><Ionicons name="cube-outline" size={18} color={C.green}/></View><View style={{flex:1}}><Text style={s.rowTitle}>{name}</Text><Text style={s.rowDetail}>{itemHistory[name]?`Ordered ${itemHistory[name].orders} times · roughly every ${itemHistory[name].every} weeks`:'No order history yet'}</Text></View><TouchableOpacity style={s.inlineAdd} onPress={()=>addNonFood(name)}><Text style={s.inlineAddText}>Add</Text></TouchableOpacity></View>)}</View>{query&&!options.length&&<Button text={`Add “${query}”`} icon="add" onPress={()=>{addNonFood(query);back()}}/>}</>}
function Compare({back,basket,checkoutShop,setCheckoutShop,delivery,setDelivery}){
 const[chosen,setChosen]=useState(checkoutShop),[stage,setStage]=useState(checkoutShop?'returned':'choose'),[timing,setTiming]=useState(delivery);
 const retailerLinks={Tesco:'https://www.tesco.com/groceries/en-GB/',Morrisons:'https://groceries.morrisons.com/',"Sainsbury's":'https://www.sainsburys.co.uk/gol-ui/groceries'};
 const sendBasket=async()=>{setStage('sent');try{await Linking.openURL(retailerLinks[chosen])}catch(e){/* Snack preview may block external tabs. */}};
 return <><Back onPress={back}/><Header overline="FULL BASKET COMPARISON" title="Choose a supermarket" sub={`${basket.length} products compared. Demo prices shown.`}/>
 {shops.map(([name,total],i)=><TouchableOpacity key={name} style={[s.shop,i===0&&s.best,chosen===name&&s.selected]} onPress={()=>{setChosen(name);setStage('choose')}}><View style={s.shopTop}><View><Text style={s.shopName}>{name}</Text><Text style={s.rowDetail}>{basket.length}/{basket.length} products matched</Text></View>{i===0&&<Text style={s.bestTag}>BEST VALUE</Text>}</View><Text style={s.shopTotal}>{money(total)}</Text><Text style={s.shopSaving}>Estimated basket total</Text>{chosen===name&&<View style={s.permission}><Ionicons name="shield-checkmark-outline" size={18} color={C.green}/><Text style={s.permissionText}>Allow Our Weekly Shop to add these {basket.length} products to your {name} basket. We cannot place the order or take payment.</Text></View>}</TouchableOpacity>)}
 {chosen&&stage==='choose'&&<><Button text={`Send this to my ${chosen} basket`} icon="open-outline" onPress={sendBasket}/><Text style={s.checkoutNote}>You will sign in securely with {chosen}. Your basket transfers there and checkout stays entirely on the supermarket website.</Text></>}
 {chosen&&stage==='sent'&&<View style={s.returnCard}><Ionicons name="open-outline" size={22} color={C.green}/><Text style={s.returnTitle}>Complete checkout with {chosen}</Text><Text style={s.returnText}>Sign in, review substitutions and pay on the {chosen} website. Then return here when your order is confirmed.</Text><Button text="I’ve checked out — continue" icon="checkmark" onPress={()=>setStage('returned')}/><TouchableOpacity onPress={sendBasket}><Text style={[s.link,{textAlign:'center',marginTop:13}]}>Open {chosen} again</Text></TouchableOpacity></View>}
 {chosen&&stage==='returned'&&<ArrivalPicker value={timing} onChange={setTiming} retailer={chosen}/>} 
 {chosen&&stage==='returned'&&<Button text="Save arrival time" icon="calendar-outline" onPress={()=>{setCheckoutShop(chosen);setDelivery(timing);back()}} disabled={!timing}/>} 
 </>;
}

function ArrivalPicker({value,onChange,retailer}){
 const[month,setMonth]=useState(8),[selectedDay,setSelectedDay]=useState(value?Number(value.split('-')[2]?.slice(0,2)):12),[hour,setHour]=useState('10'),[minute,setMinute]=useState('00');
 const monthNames=['September','October','November'];
 const days=Array.from({length:30},(_,i)=>i+1);
 const save=(day=selectedDay,hourValue=hour,minuteValue=minute)=>{setSelectedDay(day);setHour(hourValue);setMinute(minuteValue);onChange(`${monthNames[month-8]} ${day}, ${hourValue}:${minuteValue}`)};
 return <><Text style={s.sectionLabel}>WHEN WILL YOUR SHOP ARRIVE?</Text><Text style={s.deliveryHelp}>Choose the delivery or collection date and time confirmed by {retailer}.</Text><View style={s.pickerCard}><View style={s.monthRow}><TouchableOpacity disabled={month===8} onPress={()=>setMonth(m=>m-1)}><Ionicons name="chevron-back" size={20} color={month===8?C.line:C.green}/></TouchableOpacity><Text style={s.monthTitle}>{monthNames[month-8]} 2026</Text><TouchableOpacity disabled={month===10} onPress={()=>setMonth(m=>m+1)}><Ionicons name="chevron-forward" size={20} color={month===10?C.line:C.green}/></TouchableOpacity></View><View style={s.weekLabels}>{['M','T','W','T','F','S','S'].map((d,i)=><Text key={`${d}${i}`} style={s.weekLabel}>{d}</Text>)}</View><View style={s.calendarGrid}>{days.map(day=><TouchableOpacity key={day} style={[s.calendarDay,selectedDay===day&&s.calendarDayOn]} onPress={()=>save(day)}><Text style={[s.calendarDayText,selectedDay===day&&{color:C.white}]}>{day}</Text></TouchableOpacity>)}</View><Text style={s.timeLabel}>TIME</Text><View style={s.timeRow}><View style={s.timeGroup}><Text style={s.timeCaption}>Hour</Text><View style={s.timeChoices}>{['08','10','12','14','16','18','20'].map(h=><TouchableOpacity key={h} style={[s.timeChoice,hour===h&&s.timeChoiceOn]} onPress={()=>save(selectedDay,h,minute)}><Text style={[s.timeChoiceText,hour===h&&{color:C.white}]}>{h}</Text></TouchableOpacity>)}</View></View><View style={s.timeGroup}><Text style={s.timeCaption}>Minutes</Text><View style={s.timeChoices}>{['00','15','30','45'].map(m=><TouchableOpacity key={m} style={[s.timeChoice,minute===m&&s.timeChoiceOn]} onPress={()=>save(selectedDay,hour,m)}><Text style={[s.timeChoiceText,minute===m&&{color:C.white}]}>{m}</Text></TouchableOpacity>)}</View></View></View>{value&&<View style={s.pickerResult}><Ionicons name="calendar-outline" size={17} color={C.green}/><Text style={s.pickerResultText}>{value}</Text></View>}</View></>;
}
function Dates({back,dates,setDates,done}){return <><Back onPress={back}/><Header overline="PUTTING YOUR SHOP AWAY" title="Log use-by dates" sub="Only short-life products are shown. This takes under a minute and allows the app to protect food from waste."/><View style={s.card}>{Object.entries(dates).map(([name,date])=><View key={name} style={s.dateInputRow}><View style={{flex:1}}><Text style={s.rowTitle}>{name}</Text><Text style={s.rowDetail}>Use by date</Text></View><TextInput value={date} onChangeText={value=>setDates(p=>({...p,[name]:value}))} style={s.dateInput}/></View>)}</View><View style={s.info}><Ionicons name="sparkles-outline" size={19} color={C.green}/><Text style={s.infoText}>Once saved, meal order is checked automatically and earlier meal suggestions appear when needed.</Text></View><Button text="Save dates and assess meal plan" onPress={done}/></>}

function Header({overline,title,sub}){return <View style={s.header}><Text style={s.overline}>{overline}</Text><Text style={s.title}>{title}</Text><Text style={s.subtitle}>{sub}</Text></View>}
function Back({onPress}){return <TouchableOpacity style={s.back} onPress={onPress}><Ionicons name="arrow-back" size={19} color={C.green}/><Text style={s.link}>Back</Text></TouchableOpacity>}
function Button({text,onPress,icon,pale,disabled}){return <TouchableOpacity disabled={disabled} onPress={onPress} style={[s.button,pale&&s.buttonPale,disabled&&{opacity:.4}]}>{icon&&<Ionicons name={icon} size={18} color={pale?C.green:C.white}/>}<Text style={[s.buttonText,pale&&{color:C.green}]}>{text}</Text></TouchableOpacity>}
function SmallButton({icon,text,onPress,pale}){return <TouchableOpacity onPress={onPress} style={[s.smallButton,pale&&s.smallPale]}><Ionicons name={icon} size={15} color={pale?C.green:C.white}/><Text style={[s.smallText,pale&&{color:C.green}]}>{text}</Text></TouchableOpacity>}
function Nav({tab,setTab}){const tabs=[['This Week','calendar-outline','calendar'],['Plan Shop','create-outline','create'],['Basket','basket-outline','basket'],['At Home','cube-outline','cube'],['Account','person-outline','person']];return <View style={s.nav}>{tabs.map(([name,off,on])=><TouchableOpacity key={name} style={s.navItem} onPress={()=>setTab(name)}><Ionicons name={tab===name?on:off} size={20} color={tab===name?C.green:C.muted}/><Text style={[s.navText,tab===name&&s.navTextOn]}>{name}</Text></TouchableOpacity>)}</View>}
function niceDate(date){if(!date)return'No date';return new Date(`${date}T12:00:00`).toLocaleDateString('en-GB',{day:'numeric',month:'short'})}

